﻿import React from 'react';
import {AbsoluteFill,interpolateColors} from 'remotion';
import {useS,en,DUR,Easing,interpolate,clamp,FONT,Destello} from './kit';
// FE 28-nov 12:00 (historia): Ana, la oración sin voz. 2.5D con código: volumen (Vol), 3 capas con parallax, giro leve,
// sombra en el suelo, manos con dedos (Mano/Juntas) y figuras articuladas (Figura). Todo el tiempo sale de las palabras.
export const SUBS={arriba:150,size:80,acento:'#FFD84D'};
type C3=[string,string,string];
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const E=(w:string,n=1,d=.2)=>en(w,n)-d;
const mix=(a:number,b:number,t:number)=>a+(b-a)*t;
const mp=(a:[number,number],b:[number,number],t:number):[number,number]=>[mix(a[0],b[0],t),mix(a[1],b[1],t)];
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
const dirv=(a:number):[number,number]=>[Math.sin(a*Math.PI/180),-Math.cos(a*Math.PI/180)];
const SK={ana:['#ffd9b8','#e39a68','#8f4c2c'] as C3,eli:['#f6d6b8','#d9996f','#8a5232'] as C3,sam:['#f3cfae','#d28f64','#86492c'] as C3,kid:['#ffe0c8','#f5b08a','#b0603e'] as C3,
 saul:['#f4c08e','#d2864f','#7d3f1e'] as C3,dav:['#ffe3cf','#f2a784','#a8553a'] as C3,mad:['#ffd2a8','#e08e5c','#8a4426'] as C3,esp:['#f0c294','#cf8758','#7d4122'] as C3};
const HA={neg:['#5a4646','#1d1414','#060303'] as C3,bla:['#ffffff','#f0eef8','#aeaacb'] as C3,gri:['#f2f2fa','#b4b4c6','#62627a'] as C3,roj:['#ff9a5a','#e0501f','#7a1c08'] as C3,mar:['#a8744e','#5e3822','#2a140a'] as C3};
const RB={tur:['#8ffcef','#14c8c0','#04625f'] as C3,bla:['#ffffff','#ebe8fa','#9c96d0'] as C3,azu:['#7aa8ff','#3068e4','#122c80'] as C3,mar:['#ffb890','#e86a34','#8a2410'] as C3,
 mag:['#ffa6e6','#e436a4','#7a0a58'] as C3,ama:['#fff6a0','#ffc42e','#a8670a'] as C3,mor:['#d8b0ff','#8c50e6','#3e1690'] as C3,gra:['#ff9ea6','#c8283e','#620a1e'] as C3,
 nav:['#7a92f0','#2a4ac8','#0e1c70'] as C3,cue:['#f4b070','#b8641f','#5a2608'] as C3,oro:['#fff6b0','#ffc21a','#b86a08'] as C3,roa:['#ffc2dc','#f0589a','#8a1250'] as C3,
