 <linearGradient id='rayoL' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#dfe8ff' stopOpacity='.5'/><stop offset='1' stopColor='#9ab0ff' stopOpacity='0'/></linearGradient>
 <linearGradient id='oro' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#fff6b0'/><stop offset='.5' stopColor='#ffc21a'/><stop offset='1' stopColor='#b86a08'/></linearGradient>
 <linearGradient id='vino' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#ff5a6e'/><stop offset='1' stopColor='#7a0a22'/></linearGradient>
 <linearGradient id='muroT' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#4a3cdc'/><stop offset='1' stopColor='#150e5c'/></linearGradient>
