 <linearGradient id='cieloP' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#2fb0ff'/><stop offset='1' stopColor='#c4f0ff'/></linearGradient>
 <linearGradient id='muroP' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#ff7a58'/><stop offset='1' stopColor='#ffb86a'/></linearGradient>
 <linearGradient id='pisoP' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#ffd566'/><stop offset='1' stopColor='#ee8a3a'/></linearGradient>
 <linearGradient id='muroM' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#1f7fb0'/><stop offset='1' stopColor='#0a2860'/></linearGradient>
 <linearGradient id='cieloH' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#6a3ee0'/><stop offset='.5' stopColor='#ff5aa0'/><stop offset='1' stopColor='#ffc83d'/></linearGradient>
 <linearGradient id='cieloU' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#2236d0'/><stop offset='.55' stopColor='#b048e0'/><stop offset='1' stopColor='#ffb23d'/></linearGradient>
 <radialGradient id='bgR' cx='.5' cy='.45' r='.8'><stop stopColor='#ff8a3d'/><stop offset='1' stopColor='#3a0a58'/></radialGradient>
 <radialGradient id='bgG' cx='.5' cy='.45' r='.8'><stop stopColor='#fff2a8'/><stop offset='1' stopColor='#ff8a1f'/></radialGradient>
 <radialGradient id='bgL' cx='.5' cy='.45' r='.8'><stop stopColor='#3a6aff'/><stop offset='1' stopColor='#0a0a40'/></radialGradient>
 <radialGradient id='bgO' cx='.5' cy='.5' r='.8'><stop stopColor='#ffd23d'/><stop offset='.6' stopColor='#c8309c'/><stop offset='1' stopColor='#2a0a58'/></radialGradient>
 <radialGradient id='vin' cx='.5' cy='.5' r='.75'><stop offset='.62' stopColor='#000' stopOpacity='0'/><stop offset='1' stopColor='#000' stopOpacity='.5'/></radialGradient>
</defs>;
const BGC:Record<string,[string,string]>={R:['#ff8a3d','#3a0a58'],T:['#6a5cf0','#0b0830'],P:['#ffd23d','#ff6a3d'],L:['#4a7aff','#0a0a40'],S:['#6a5cf0','#0b0830'],M:['#ff9a4a','#14083a'],H:['#ff7aa8','#2a1a6a'],U:['#ffc23d','#3a1a7a'],O:['#ffd23d','#3a0a58']};
const Bokeh:React.FC<{s:number;w:string;cerca?:boolean}>=({s,w,cerca=false})=><g>{Array.from({length:cerca?6:14}).map((_,j)=>{const r=cerca?60+((j*37+w.charCodeAt(0)*11)%70):16+((j*29+w.charCodeAt(0)*7)%40);const x=((j*263+w.charCodeAt(0)*97)%1500)-210,y=((j*389+w.charCodeAt(0)*151)%2300)-190;return <circle key={j} cx={x+Math.sin(s*.6+j)*30} cy={y+Math.cos(s*.5+j)*30} r={r} fill={cerca?'#fff':BGC[w][0]} opacity={cerca?.17:.35} filter={cerca?'url(#b18)':'url(#b6)'}/>;})}</g>;
const Polvo:React.FC<{s:number;n?:number;col?:string;x0?:number;x1?:number;y0?:number;y1?:number}>=({s,n=36,col='#ffe9a0',x0=-200,x1=1300,y0=200,y1=1700})=><g>{Array.from({length:n}).map((_,j)=>{const x=x0+((j*211)%(x1-x0))+Math.sin(s*.7+j)*26,y=y0+((j*337)%(y1-y0))-((s*(14+j%5*6))%(y1-y0))*.0+Math.cos(s*.5+j*1.3)*34;const tw=.45+.45*Math.sin(s*2.2+j*1.7);return <circle key={j} cx={x} cy={y} r={3+(j%4)*1.6} fill={col} opacity={tw}/>;})}</g>;
// ---------- cápsula con volumen barato (dedos, brazos, cuellos) ----------
const Cap:React.FC<{a:[number,number];b:[number,number];w:number;c:C3}>=({a,b,w,c})=>{const[x1,y1]=a,[x2,y2]=b;
 return <g><path d={caps(x1,y1,x2,y2,w)} fill={c[1]} stroke={c[2]} strokeWidth={2.4} strokeOpacity={.75}/>
 <path d={caps(x1+w*.1,y1+w*.1,x2+w*.1,y2+w*.1,w*.4)} fill={c[2]} opacity={.26}/>
 <path d={caps(x1-w*.14,y1-w*.14,x2-w*.14,y2-w*.14,w*.36)} fill={c[0]} opacity={.6}/></g>;};
const Tapered:React.FC<{a:[number,number];b:[number,number];r1:number;r2:number;c:C3}>=({a,b,r1,r2,c})=>{const an=Math.atan2(b[1]-a[1],b[0]-a[0]),nx=-Math.sin(an),ny=Math.cos(an);
 const d=`M${a[0]+nx*r1} ${a[1]+ny*r1}L${b[0]+nx*r2} ${b[1]+ny*r2}A${r2} ${r2} 0 0 0 ${b[0]-nx*r2} ${b[1]-ny*r2}L${a[0]-nx*r1} ${a[1]-ny*r1}A${r1} ${r1} 0 0 0 ${a[0]+nx*r1} ${a[1]+ny*r1}Z`;
 return <g><path d={d} fill={c[1]} stroke={c[2]} strokeWidth={2.4} strokeOpacity={.7}/>
 <path d={caps(a[0]+nx*-r1*.35,a[1]+ny*-r1*.35,b[0]+nx*-r2*.35,b[1]+ny*-r2*.35,r1*.5)} fill={c[0]} opacity={.55}/>
 <path d={caps(a[0]+nx*r1*.45,a[1]+ny*r1*.45,b[0]+nx*r2*.45,b[1]+ny*r2*.45,r1*.45)} fill={c[2]} opacity={.3}/></g>;};
// ---------- manos con volumen: palma, 4 dedos con dos falanges y uñas, pulgar (apunta hacia arriba en su marco) ----------
const Mano:React.FC<{x:number;y:number;r?:number;c:C3;ab?:number;cu?:number[];th?:number;k?:number;old?:boolean;lado?:number}>=({x,y,r=0,c,ab=.4,cu=[0,0,0,0],th=.5,k=1,old=false,lado=1})=>{
 const LN=[46,54,50,40],WD=[15.5,16,15.5,13.5];
 const dedos=[0,1,2,3].map(i=>{const bx=-23+i*15.5,by=-62+(i===1||i===2?-5:i===3?1:0),a=(i-1.5)*ab*15-(i===0?2:0),len=LN[i]*(1-.58*cu[i]),s1=len*.55,s2=len*.45,bend=cu[i]*48;
  const d1=dirv(a),d2=dirv(a+bend),p1:[number,number]=[bx+d1[0]*s1,by+d1[1]*s1],p2:[number,number]=[p1[0]+d2[0]*s2,p1[1]+d2[1]*s2];return{bx,by,p1,p2,a:a+bend,i,w:WD[i]};});
 const ta=-72+(1-th)*52,t0:[number,number]=[-27,-10],td=dirv(ta),t1:[number,number]=[t0[0]+td[0]*33,t0[1]+td[1]*33],td2=dirv(ta+24),t2:[number,number]=[t1[0]+td2[0]*27,t1[1]+td2[1]*27];
 return <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k*lado} ${k})`}>
  <path d='M-31 2C-37 -24 -35 -48 -31 -66C-10 -73 10 -73 31 -66C35 -48 37 -24 31 2C16 15 -16 15 -31 2Z' fill={c[1]} stroke={c[2]} strokeWidth={2.4} strokeOpacity={.7}/>
  <ellipse cx={-9} cy={-38} rx={13} ry={24} fill={c[0]} opacity={.5}/><ellipse cx={15} cy={-14} rx={14} ry={9} fill={c[2]} opacity={.22}/>
  <path d='M-14 -20Q2 -33 20 -22' stroke={c[2]} strokeWidth={2.2} fill='none' opacity={.4}/>
  {old&&<><path d='M-12 -62Q-8 -36 -14 -8M6 -62Q8 -36 4 -12M18 -58Q22 -36 20 -16' stroke='#6c7ec4' strokeWidth={4} fill='none' opacity={.4} strokeLinecap='round'/>{dedos.map(d=><ellipse key={d.i} cx={d.bx} cy={d.by+4} rx={8} ry={5} fill={c[2]} opacity={.3}/>)}</>}
  <Cap a={t0} b={t1} w={19} c={c}/><Cap a={t1} b={t2} w={17} c={c}/><circle cx={t1[0]} cy={t1[1]} r={9} fill={c[1]}/>
  <ellipse cx={t2[0]-td2[0]*4} cy={t2[1]-td2[1]*4} rx={5} ry={6.5} fill='#ffeee8' opacity={.8} transform={`rotate(${ta+24} ${t2[0]} ${t2[1]})`}/>
  {dedos.map(d=><g key={d.i}><Cap a={[d.bx,d.by+6]} b={d.p1} w={d.w} c={c}/><circle cx={d.p1[0]} cy={d.p1[1]} r={d.w*.5} fill={c[1]}/><Cap a={d.p1} b={d.p2} w={d.w-1.5} c={c}/>
   <path d={`M${d.p1[0]-5} ${d.p1[1]}Q${d.p1[0]} ${d.p1[1]-2} ${d.p1[0]+5} ${d.p1[1]}`} stroke={c[2]} strokeWidth={1.8} fill='none' opacity={.55}/>
   {cu[d.i]<.85&&<ellipse cx={d.p2[0]-dirv(d.a)[0]*4} cy={d.p2[1]-dirv(d.a)[1]*4} rx={4.6} ry={6} fill='#ffeee8' opacity={.8} transform={`rotate(${d.a} ${d.p2[0]} ${d.p2[1]})`}/>}</g>)}
 </g>;};
// manos entrelazadas en oración: palma, dedos que se cruzan y dos pulgares
const Juntas:React.FC<{x:number;y:number;r?:number;k?:number;c:C3}>=({x,y,r=0,k=1,c})=><g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
 <ellipse cx={0} cy={60} rx={74} ry={16} fill='#000' opacity={.25} filter='url(#b6)'/>
 <path d='M-72 20C-78 -30 -36 -58 0 -58C36 -58 78 -30 72 20C60 62 30 74 0 74C-30 74 -60 62 -72 20Z' fill={c[1]} stroke={c[2]} strokeWidth={2.5} strokeOpacity={.7}/>
