</g>;
// ---------- rostro: ojos con iris, párpados y punto blanco, cejas, nariz con fosas, boca que cambia, lágrimas, pelo y velo ----------
type Ex={c?:number;a?:number;b?:number;e?:number;l?:number};
const FP='M0 -78C40 -78 61 -46 61 -6C61 40 39 80 0 86C-39 80 -61 40 -61 -6C-61 -46 -40 -78 0 -78Z';
const HC='M-63 -8C-72 -92 -32 -102 0 -102C34 -102 74 -92 63 -8C58 -46 32 -62 0 -60C-32 -62 -58 -46 -63 -8Z';
const Cara:React.FC<{id:string;s:number;skin:C3;hair:C3;estilo:string;beard:C3|null;velo:C3|null;ex:Ex;yaw:number;look:number;mujer:boolean;iris:string;old:boolean}>=({id,s,skin,hair,estilo,beard,velo,ex,yaw,look,mujer,iris,old})=>{
 const{c=.2,a=0,b=.2,e=.85,l=0}=ex,yy=yaw*9,seed=id.charCodeAt(0)*.37+id.length,p=((s*.31+seed)%1),bl=Math.max(0,1-Math.abs(p-.03)/.03),eo=Math.max(.06,e*(1-bl*.95));
 const lip=mujer?['#ffb6c6','#e0506f','#8a1f3c']:['#f0b09a','#c27058','#7a3a2a'],yc=56,open=a*15,cy=yc-c*7,cl=`${-22+yy} ${cy}`,cr=`${22+yy} ${cy}`;
 return <g>
  {estilo==='canoso'&&<Vol id={id+'hb'} d='M-68 -30C-86 40 -76 130 -62 168C-30 182 30 182 62 168C76 130 86 40 68 -30Z' c={hair} sw={40} o={10}/>}
  {estilo==='velo'&&<path d='M-66 -30C-80 40 -70 110 -64 150L64 150C70 110 80 40 66 -30Z' fill={HA.neg[1]}/>}
  {[-1,1].map(k=><g key={k}><ellipse cx={k*60} cy={4} rx={11} ry={22} fill={skin[1]} stroke={skin[2]} strokeWidth={2} strokeOpacity={.6}/><ellipse cx={k*60-k*1} cy={4} rx={5} ry={12} fill={skin[2]} opacity={.35}/></g>)}
  <Vol id={id+'f'} d={FP} c={skin} sw={38} o={9}/>
  {[-1,1].map(k=><ellipse key={k} cx={k*38+yy} cy={30} rx={22} ry={14} fill={mujer?'#ff6f8a':'#ff8a8a'} opacity={l>0?.34:.2} filter='url(#b6)'/>)}
  {old&&<g stroke={skin[2]} strokeWidth={2.4} fill='none' opacity={.4} strokeLinecap='round'><path d='M-34 -52Q0 -60 34 -52M-30 -43Q0 -50 30 -43'/><path d={`M${-26+yy} 28Q${-32+yy} 44 ${-24+yy} 56M${26+yy} 28Q${32+yy} 44 ${24+yy} 56`}/><path d='M-52 -4L-44 -2M-52 4L-44 2M52 -4L44 -2M52 4L44 2'/></g>}
  {[-1,1].map(k=>{const X=k*27+yy,op=eo;return <g key={k} transform={`translate(${X} -6)`}>
   {l>0&&<ellipse rx={24} ry={16} fill='#ff4a6e' opacity={.3*l} filter='url(#b6)'/>}
   <defs><clipPath id={id+'e'+k}><path d={`M-17 1Q0 ${-17*op} 17 1Q0 ${15*op+1} -17 1Z`}/></clipPath></defs>
   <path d={`M-17 1Q0 ${-17*op} 17 1Q0 ${15*op+1} -17 1Z`} fill={l>0?'#ffdde0':'#fff'}/>
   <g clipPath={`url(#${id}e${k})`}><circle cx={look*5} cy={0} r={9} fill={iris}/><circle cx={look*5} cy={0} r={5} fill='#050505'/><circle cx={look*5-3} cy={-4} r={3.2} fill='#fff'/><circle cx={look*5+3} cy={3} r={1.5} fill='#fff' opacity={.8}/><path d={`M-17 -4Q0 ${-20*op} 17 -4L17 -20L-17 -20Z`} fill={skin[2]} opacity={.28}/></g>
   <path d={`M-18 1Q0 ${-18*op} 18 1`} stroke={hair[2]} strokeWidth={4.4} fill='none' strokeLinecap='round'/>
   <path d={`M-16 2Q0 ${16*op+1} 16 2`} stroke={skin[2]} strokeWidth={1.8} fill='none' opacity={.6}/>
   {mujer&&[0,1,2].map(j=><path key={j} d={`M${k*14+k*j*3} ${-6-j*2}L${k*(22+j*2)} ${-14-j*3}`} stroke={hair[2]} strokeWidth={2.4} strokeLinecap='round'/>)}
